DOMAIN='Use the lecture’s vertical-plane two-revolute model: massless links of positive lengths l1,l2, endpoint point masses m1,m2, theta1 measured counterclockwise from +X0, theta2 relative to link1, +Y0 upward, physical gravity −g Y0 with g≥0. Positive joint torques increase their joint angles. No terminal wrench, friction or motor inertia unless explicitly changed.'
def form(expression,variables,units,assumptions=None):return {'expression':expression,'variables':variables,'units':units,'assumptions':assumptions or []}
KIN=form('omega1=[0,0,q1dot]; alpha1=[0,0,q1ddot]; omega2=[0,0,q1dot+q2dot]; alpha2=[0,0,q1ddot+q2ddot]',{'omega1,omega2':'angular velocities in their respective link frames','alpha1,alpha2':'angular accelerations in their respective link frames','q1dot,q2dot':'joint angular rates','q1ddot,q2ddot':'joint angular accelerations'},{'omega1,omega2,q1dot,q2dot':'rad/s','alpha1,alpha2,q1ddot,q2ddot':'rad/s²'},['Fixed nonrotating base; parallel +z revolute axes.'])
ACC1=form('a1¹=[g sin(theta1),g cos(theta1),0]; aC1¹=[−l1 q1dot²+g sin(theta1),l1 q1ddot+g cos(theta1),0]',{'a1¹':'gravity-augmented link1-origin acceleration in frame1','aC1¹':'gravity-augmented first mass acceleration in frame1','l1':'first-link length','theta1':'first joint angle','q1dot':'first joint rate','q1ddot':'first joint acceleration','g':'positive gravitational acceleration magnitude'},{'a1¹,aC1¹,g':'m/s²','l1':'m','theta1':'rad','q1dot':'rad/s','q1ddot':'rad/s²'},['Gravity enters through fictitious base acceleration +g Y0, not physical base motion.'])
ACC2=form('a2²=[l1 sin(theta2) q1ddot−l1 cos(theta2) q1dot²+g sin(theta1+theta2),l1 cos(theta2) q1ddot+l1 sin(theta2) q1dot²+g cos(theta1+theta2),0]; aC2²=a2²+[−l2(q1dot+q2dot)²,l2(q1ddot+q2ddot),0]',{'a2²':'gravity-augmented elbow-origin acceleration in frame2','aC2²':'gravity-augmented second mass acceleration in frame2','l1,l2':'link lengths','theta1,theta2':'first and relative second joint angles','q1dot,q2dot':'joint angular rates','q1ddot,q2ddot':'joint angular accelerations','g':'gravitational magnitude'},{'a2²,aC2²,g':'m/s²','l1,l2':'m','theta1,theta2':'rad','q1dot,q2dot':'rad/s','q1ddot,q2ddot':'rad/s²'},[DOMAIN])
DYN=form('tau1=m2 l2²(q1ddot+q2ddot)+m2 l1 l2 cos(theta2)(2q1ddot+q2ddot)+(m1+m2)l1² q1ddot−m2 l1 l2 sin(theta2)(q2dot²+2q1dot q2dot)+m2 l2 g cos(theta1+theta2)+(m1+m2)l1 g cos(theta1); tau2=m2 l1 l2 cos(theta2)q1ddot+m2 l1 l2 sin(theta2)q1dot²+m2 l2 g cos(theta1+theta2)+m2 l2²(q1ddot+q2ddot)',{'tau1,tau2':'positive actuator torques required for prescribed motion','m1,m2':'endpoint point masses','l1,l2':'link lengths','theta1,theta2':'first and relative second joint angles','q1dot,q2dot':'joint rates','q1ddot,q2ddot':'joint accelerations','g':'positive gravity magnitude'},{'tau1,tau2':'N·m','m1,m2':'kg','l1,l2':'m','theta1,theta2':'rad','q1dot,q2dot':'rad/s','q1ddot,q2ddot':'rad/s²','g':'m/s²'},[DOMAIN])
def note(p,text,exclude=None):NOTES[p]={'text':text,'exclude':exclude}
def issue(p,text):ISSUES.append({'physicalPage':p,'description':text,'status':'qualified_not_silently_repaired'})
def add(key,title,pages,stem,opts,why,steps=None,formulas=None,kind='conceptual',difficulty='medium',correct=(0,),assumptions=None,angle=None,trap=None,memory=None,prereq=None):
 n=len(Q)+1;qid=f'{BATCH}-Q{n:03d}';cid=f'{BATCH}-C-{key}';ids=[f'o{(j+n)%len(opts)+1}' for j in range(len(opts))];options=[{'id':ids[j],'text':o[0]} for j,o in enumerate(opts)];options.sort(key=lambda o:hashlib.sha256((qid+o['id']).encode()).hexdigest())
 citations=[]
 for p in pages:
  citations.append({'slideId':f'lectures-p{p:04d}','sourceId':'lectures','sourceSha256':SOURCE,'physicalPage':p,'kind':'figure' if kind=='diagram' else ('equation' if formulas else 'statement'),'locator':f'Lecture13, physical PDF page {p}, printed slide {p-403}: '+title,'evidenceText':(R/f'sources/text/lectures/page-{p:04d}.txt').read_text().strip(),'role':'premise' if kind in ('numerical','derivation','scenario') else 'explicit','region':None})
 q={'id':qid,'version':1,'status':'draft','authorId':AUTHOR,'stem':stem,'selectionMode':'multi' if len(correct)>1 else 'single','type':kind,'difficulty':difficulty,'cognitiveSkill':'numerical' if kind=='numerical' else ('synthesis' if difficulty in ('hard','extremely_tricky') else ('recall' if kind in ('definition','match') else 'application' if kind in ('derivation','scenario') else 'conceptual')),'week':3,'lectureId':'L13','topic':'Newton–Euler inverse dynamics','subtopic':title,'tags':[key,'point-mass-2R'],'conceptIds':[cid],'assumptions':assumptions or [],'options':options,'correctOptionIds':[ids[j] for j in correct],'citations':citations,'solution':{'justification':why,'optionExplanations':{ids[j]:o[1] for j,o in enumerate(opts)},'steps':steps or [],'formulas':formulas or [],'simpleExplanation':why,'memoryAid':memory,'misconceptions':[o[1] for j,o in enumerate(opts) if j not in correct],'examTraps':[trap] if trap else [],'prerequisiteConceptIds':prereq or []},'origin':'generated','reviewIds':[]};Q.append(q)
 if cid not in C:C[cid]={'id':cid,'title':title,'description':why,'slideIds':[],'questionIds':[],'status':'drafted','topic':q['topic'],'subtopic':title,'prerequisiteConceptIds':prereq or [],'examinationAngles':[]}
 c=C[cid];c['questionIds'].append(qid);c['slideIds']=sorted(set(c['slideIds']+[x['slideId'] for x in citations]));c['examinationAngles']=sorted(set(c['examinationAngles']+[angle or kind]));return cid

def save(frozen=False):
 slides={s['id']:s for s in map(json.loads,(R/'sources/page_maps/lectures.jsonl').read_text().splitlines())};oldpath=R/f'data/inspection-batches/{BATCH}.json';old={s['physicalPage']:s for s in json.loads(oldpath.read_text())['slides']} if oldpath.exists() else {};outslides=[]
 for p,info in sorted(NOTES.items()):
  s=copy.deepcopy(slides[f'lectures-p{p:04d}']);s['disposition']='excluded' if info['exclude'] else 'examinable';s['exclusionReason']=info['exclude'];s['conceptIds']=[c['id'] for c in C.values() if s['id'] in c['slideIds']];s['visualInspection']={'status':'complete','inspectorId':AUTHOR,'inspectedAt':old.get(p,{}).get('visualInspection',{}).get('inspectedAt',now),'method':'rendered_page','notes':info['text']+' Actual 1800×1013 rendered pixels were viewed; not an extraction-only inspection.','previewSha256':hashlib.sha256((R/s['previewPath']).read_bytes()).hexdigest(),'dimensions':[1800,1013]};outslides.append(s)
 batch={'schemaVersion':'1.0.0','batchId':BATCH,'authorId':AUTHOR,'questions':Q,'concepts':list(C.values()),'sourceIssues':ISSUES,'coverageNote':('Author batch frozen for separate independent review; no claim of verified or exhaustive coverage.' if frozen else 'Incremental source-inspected draft; unfinished pages/angles and independent review remain.')}
 for typ,records in [('question',Q),('concept',C.values()),('slide',outslides)]:
  sch=json.loads((R/f'data/schema.{typ}.json').read_text());errors=[e for r in records for e in schema_errors(r,sch)];assert not errors,(typ,errors)
 for rel,obj in [(f'data/question-batches/{BATCH}.json',batch),(f'data/inspection-batches/{BATCH}.json',{'batchId':BATCH,'slides':outslides})]:(R/rel).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
 packet=[{**{k:q[k] for k in ['id','version','stem','selectionMode','type','difficulty','options','assumptions']},'questionSha256':question_hash(q),'citations':[{k:v for k,v in c.items() if k!='evidenceText'} for c in q['citations']]} for q in Q];(R/f'audits/blind-{BATCH}.json').write_text(json.dumps(packet,ensure_ascii=False,indent=2)+'\n')
 hashes={'batchId':BATCH,'frozen':frozen,'questions':[{'id':q['id'],'version':q['version'],'questionSha256':question_hash(q)} for q in Q],'batchSha256':hashlib.sha256((R/f'data/question-batches/{BATCH}.json').read_bytes()).hexdigest(),'blindPacketSha256':hashlib.sha256((R/f'audits/blind-{BATCH}.json').read_bytes()).hexdigest()};(R/f'audits/{BATCH}-question-hashes.json').write_text(json.dumps(hashes,indent=2)+'\n')
 (R/'docs/handoffs/L13-author.md').write_text(f'# L13 authoring recovery\n\nOwner: {AUTHOR}. Physical pages404–427, Week3. Persisted {len(outslides)} actual page inspections, {len(C)} concept records and {len(Q)} draft questions. Frozen for independent review: {frozen}.\n\nAuthor source: scripts/author_W03_L13.py. Draft batch: data/question-batches/W03-L13.json. Inspection ledger: data/inspection-batches/W03-L13.json. Answer-free packet: audits/blind-W03-L13.json, citation evidenceText omitted. Hash manifest: audits/W03-L13-question-hashes.json.\n\nNo self-approval, canonical bank edits or Git actions. Continue remaining source observations, meaningful angles and independent-method numeric checks before final freeze. All source conventions and ambiguities stay explicit.\n')
 print(json.dumps({'questions':len(Q),'concepts':len(C),'inspected':len(NOTES),'frozen':frozen,**{k:hashes[k] for k in ['batchSha256','blindPacketSha256']}}))

note(404,'Printed1 title Newton–Euler’s Equation: Examples, Lecture13, IIT Roorkee lecturer and campus image.','Lecture title and institutional branding; no new technical proposition.')
note(405,'Printed2 learning objective: analytically solve a dynamic manipulator problem.','Learning objective only; no additional technical equation or definition.')
note(406,'Printed3 contents: 2DOF planar example, outward iterations, inward iterations.','Outline only; actual technical procedure occurs on subsequent pages.')
note(407,'Printed4 two-revolute arm diagram. m1 at elbow/distal end of l1, m2 at tip/distal end of l2. theta1 from horizontal, theta2 relative to first-link extension. Joint torque arrows are positive joint-angle sense. All mass concentrated at distal points.')
note(408,'Printed5 COM offsets l1 x1 and l2 x2. COM inertia tensors zero for point masses. Terminal f3=n3=0, omega0=alpha0=0; fictitious base linear acceleration +g Y0 includes physical downward gravity. Figure labels frame1 at base, frame2 at elbow, frame3 at tip.')
note(409,'Printed6 rotations R_(i,i+1)=[[c,-s,0],[s,c,0],[0,0,1]] and reverse transpose. Link1 outward iteration i=0 gives omega1=[0,0,q1dot] because base is nonrotating.')
issue(408,'The phrase “No external force acting” is immediately followed by gravity inclusion. Interpret it as no externally applied terminal wrench, not absence of gravitational body forces. The +g Y0 base seed is a gravity bookkeeping device, not actual base acceleration.')
add('model-masses','Endpoint masses and frame locations',[407,408],'Which mass placement matches the lecture’s two-link model?', [('m1 at the elbow and m2 at the tip; the links carry no distributed mass','These are the stated distal point masses.'),('m1 and m2 at their respective link midpoints','Midpoint COMs describe a different mass distribution.'),('Both masses at the final tip','This moves m1 away from the first-link distal end.'),('m1 at the fixed base and m2 at the elbow','Those are proximal rather than the stated distal locations.')], 'The first link ends at the elbow, while the second ends at the tool tip. Their masses are idealized at those two points.',kind='diagram',difficulty='easy')
add('com-inertia','Zero COM inertia does not mean zero joint inertia',[408],'An endpoint point mass has zero inertia tensor about its own COM. Which conclusion is valid?', [('It can still require joint torque because its force acts at a nonzero joint-to-COM offset','A displaced point mass has translational kinetic energy and an offset-force moment.'),('It contributes no inertial joint torque for any joint acceleration','Zero COM spin inertia does not remove offset translational inertia.'),('Its inertia about the joint axis is also zero regardless of the offset','The parallel-axis contribution is nonzero off the axis.'),('Its mass must be zero because its COM inertia tensor is zero','A finite ideal point mass has zero extent about its own location.')], 'A zero COM inertia tensor removes the local spin moment I alpha + omega×I omega, not the moment r×ma about a displaced joint.',trap='Do not substitute zero COM inertia for zero inertia about every origin.')
add('com-inertia','Zero COM inertia does not mean zero joint inertia',[407,408],'As a one-link specialization, a 2 kg point mass is 0.5 m from a fixed revolute joint. With gravity suppressed and angular acceleration 3 rad/s², what inertial torque is required?', [('1.5 N·m','m l² alpha=2×0.25×3=1.5.'),('0 N·m','This incorrectly uses the zero COM inertia about the displaced joint.'),('3 N·m','This uses m l alpha and omits one lever-arm factor.'),('6 N·m','This drops the length-squared factor entirely.')], 'The tangential force is m l alpha=3 N and its moment arm is 0.5 m, giving 1.5 N·m.',steps=['Tangential acceleration=l alpha=0.5×3=1.5 m/s².','Tangential force=m a=2×1.5=3 N.','Torque=l F=0.5×3=1.5 N·m.'],formulas=[form('tau=m l² alpha',{'tau':'joint torque','m':'point mass','l':'joint-to-mass distance','alpha':'angular acceleration'},{'tau':'N·m','m':'kg','l':'m','alpha':'rad/s²'},['Single-link derived specialization; no gravity or terminal load.'])],kind='numerical',assumptions=['This is a derived one-link specialization of the stated endpoint-mass assumption, not a new supplied slide value.'])
add('gravity-boundary','Terminal boundary and gravity initialization',[408],'Which statements are consistent with the example? Select all that apply.', [('The terminal wrench is zero: f3=0 and n3=0','No end-effector interaction load is applied.'),('The +g Y0 base acceleration seed includes physical gravity without moving the base','The seed implements the gravity contribution in the recursion.'),('The zero terminal wrench means every internal link force is zero','Internal forces are needed to accelerate and support the masses.'),('The zero base angular velocity forces both joint angular rates to zero','Relative joint rates may be nonzero while the base stays fixed.')], 'A fixed base, gravity compensation and moving joints coexist. Zero terminal wrench removes only the boundary contact load.',correct=(0,1),kind='multiple_select',trap='Zero boundary load does not imply zero internal load.')
add('gravity-boundary','Terminal boundary and gravity initialization',[408],'For physical gravitational acceleration (0,−9.81,0) m/s² in frame0, which initialization includes gravity using the slide’s convention?', [('Seed a0=(0,+9.81,0) m/s² and do not add the same gravity contribution again as a body-force load','The opposite-gravity seed generates the support-torque term once.'),('Seed a0=(0,−9.81,0) m/s² and use the same outward equations unchanged','This reverses the compensation sign.'),('Seed a0=0 and omit gravity loads everywhere','This computes gravity-free dynamics instead.'),('Seed a0=(0,+9.81,0) m/s² and add identical gravity-compensation terms again','This double-counts gravity.')], 'The recursion uses a fictitious acceleration opposite physical gravity. It is an accounting convention, not an upward-moving support.',kind='scenario',assumptions=['The physical base is stationary and no separate gravitational body-force terms are added.'])
add('relative-rotation','Direction of successive frame rotations',[409],'A vector has components (1,0,0) in frame1. If theta2=+90°, what are its components in frame2?', [('(0,−1,0)','R21=Rz(−90°) maps +x1 to −y2.'),('(0,+1,0)','This applies R12 rather than R21.'),('(1,0,0)','This ignores the relative orientation.'),('(−1,0,0)','This applies 180° instead of the stated 90°.')], 'Changing from frame1 to frame2 uses the transpose of the frame2-to-frame1 rotation.',steps=['Use R21=[[cos theta2,sin theta2,0],[-sin theta2,cos theta2,0],[0,0,1]].','At 90°, its first column is (0,−1,0).','Multiplication by (1,0,0) selects that column.'],formulas=[form('v²=Rz(−theta2)v¹',{'v¹,v²':'same vector components in frame1 and frame2','theta2':'relative frame rotation'},{'v¹,v²':'same units as the original vector','theta2':'rad'})],kind='numerical')
add('angular-link1','First-link angular propagation',[409],'The base is nonrotating but q1dot=−2 rad/s. What is the first link’s angular velocity expressed in frame1?', [('(0,0,−2) rad/s','The relative joint rate remains with its signed +z component.'),('(0,0,+2) rad/s','A rate magnitude is not the signed angular velocity.'),('(0,0,0) rad/s','A fixed base does not suppress relative joint motion.'),('(−2,0,0) rad/s','The revolute axis is +z, not the link’s x direction.')], 'With omega0=0, only q1dot z1 remains in the outward recursion.',steps=['Rotate the zero base angular velocity: still zero.','Add q1dot z1 with z1=(0,0,1).','Obtain (0,0,−2) rad/s.'],formulas=[KIN],kind='numerical',difficulty='easy')
note(410,'Printed7 full angular-acceleration recursion including transported omega cross relative joint rate. With nonrotating base, alpha1=[0,0,q1ddot]. Figure retains endpoint masses and joint-axis senses.')
note(411,'Printed8 origin acceleration R10[0,g,0]=[g s1,g c1,0]. COM acceleration is alpha1 cross rC1 plus omega1 cross(omega1 cross rC1) plus origin acceleration; expanded skew matrices show tangential +y and centripetal −x signs.')
note(412,'Printed9 collected aC1=[−l1 q1dot²+g s1,l1 q1ddot+g c1,0], F1=m1 aC1. Capital N1=I_C1 alpha1+omega1 cross(I_C1 omega1)=0, not generally the inward joint moment n1.')
note(413,'Printed10 outward link2 uses i=1. R21 leaves the common z vector unchanged, so omega2=[0,0,q1dot+q2dot]. Relative rate adds, not replaces inherited rate.')
note(414,'Printed11 angular-acceleration transport cross term vanishes because both angular vectors are along z. alpha2=[0,0,q1ddot+q2ddot]. This planar result is not a general spatial-axis identity.')
note(415,'Printed12 elbow origin and first COM coincide because first point mass is at distal link endpoint: p12=pC1. Thus a2²=R21 aC1¹. Components l1 s2 q1ddot−l1 c2 q1dot²+g s12 and l1 c2 q1ddot+l1 s2 q1dot²+g c12. s12/c12 mean angle sum, not products.')
note(416,'Printed13 aC2² adds relative-to-elbow tangential [0,l2(q1ddot+q2ddot),0] and centripetal [−l2(q1dot+q2dot)²,0,0] to a2². Squared total angular rate includes the mixed 2 q1dot q2dot term.')
note(417,'Printed14 F2=m2 aC2 with all inherited, combined-rate and gravity terms shown. N2=0 because I_C2=0. Zero spin moment does not remove F2 or its moment about elbow.')
issue(415,'The text attributes p12=pC1 to a point mass. More precisely this equality needs the stated distal-end location; a point mass placed elsewhere on link1 would not make its COM coincide with the elbow.')
add('angular-acceleration','Angular acceleration transport',[410,414],'Why is the angular-acceleration transport cross term zero in this planar example?', [('The transported upstream angular velocity and the relative joint angular velocity are parallel to the same z axis','Parallel vectors have zero cross product.'),('All angular accelerations are assumed zero','The equations retain q1ddot and q2ddot.'),('A fixed base forces every cross product in every moving link to vanish','Moving links still have nonzero offset and centripetal cross products.'),('The point-mass inertia assumption makes the angular kinematics zero','Inertia affects force/moment requirements, not this kinematic cross-product identity.')], 'The vanishing term is a parallel-axis kinematic fact. It does not imply zero accelerations or zero centripetal forces.',formulas=[KIN],trap='Do not generalize the planar parallel-axis simplification to arbitrary spatial joints.')
add('origin-acceleration','Gravity-augmented origin acceleration',[408,411],'At theta1=90° and g=10 m/s², what is the recursion’s frame1-origin acceleration vector, expressed in frame1?', [('(10,0,0) m/s²','R10 rotates +g Y0 into +x1.'),('(0,10,0) m/s²','This leaves the seed in base coordinates.'),('(−10,0,0) m/s²','This reverses the gravity-bookkeeping sign.'),('(0,0,0) m/s²','The physical origin is fixed, but the gravity-augmented recursion seed is not zero.')], 'The vector here includes fictitious gravity compensation. It is not the physical acceleration of the fixed base origin.',steps=['Start from a0=(0,10,0) in base coordinates.','Apply R10=Rz(−90°).','The result is (10,0,0) in frame1.'],formulas=[ACC1],kind='numerical',assumptions=[DOMAIN],trap='Keep physical acceleration distinct from gravity-augmented recursion acceleration.')
add('com-terms','Tangential and centripetal acceleration',[411,412],'In frame1 with rC1=(l1,0,0), which ordered pair gives alpha1×rC1 and omega1×(omega1×rC1)?', [('(0,l1 q1ddot,0) and (−l1 q1dot²,0,0)','Tangential acceleration is +y for positive alpha; centripetal acceleration is toward the origin.'),('(0,l1 q1dot²,0) and (−l1 q1ddot,0,0)','This exchanges the acceleration and squared-rate roles.'),('(0,−l1 q1ddot,0) and (+l1 q1dot²,0,0)','Both cross-product signs are reversed.'),('(l1 q1ddot,0,0) and (0,−l1 q1dot²,0)','This swaps radial and tangential directions.')], 'For a +z axis, z×x=y and z×y=−x. The nested product therefore points radially inward.',steps=['alpha1=(0,0,q1ddot), so alpha1×rC1=(0,l1 q1ddot,0).','omega1×rC1=(0,l1 q1dot,0).','Cross once more with omega1 to obtain (−l1 q1dot²,0,0).'],formulas=[ACC1],kind='derivation',memory='One cross turns x toward y; a second turns y toward −x.')
add('com-terms','Tangential and centripetal acceleration',[411,412],'At an instant q1dot=0 but q1ddot≠0, which motion-dependent contribution to aC1 remains?', [('Tangential l1 q1ddot along y1, while the centripetal term is zero','The squared-rate term vanishes but acceleration need not.'),('Centripetal −l1 q1ddot along x1, while the tangential term is zero','Angular acceleration is not a replacement for squared speed in the radial term.'),('Both terms vanish because the joint is momentarily at rest','Momentary zero velocity does not imply zero acceleration.'),('Both terms remain with equal magnitudes l1 q1ddot','The centripetal term depends on q1dot², not q1ddot.')], 'A joint can be at a turning point with zero speed and nonzero angular acceleration. Gravity is a separate additive term.',formulas=[ACC1])
add('first-force','First-link COM acceleration and force',[412],'Let l1=0.5 m, m1=2 kg, theta1=0°, q1dot=2 rad/s, q1ddot=3 rad/s² and g=10 m/s². What is F1 expressed in frame1?', [('(−4,23,0) N','aC1=(−2,11.5,0), then multiply both components by2.'),('(−2,11.5,0) N','These are acceleration components, not force components.'),('(+4,23,0) N','The centripetal contribution must point along −x1.'),('(−4,3,0) N','This omits the 20 N gravity contribution in y1.')], 'The first mass needs both inward centripetal force and tangential-plus-gravity support force.',steps=['aC1,x=−0.5×2²+10 sin0=−2 m/s².','aC1,y=0.5×3+10 cos0=11.5 m/s².','F1=2 aC1=(−4,23,0) N.'],formulas=[ACC1,form('F1=m1 aC1¹',{'F1':'first mass force in frame1','m1':'first point mass','aC1¹':'gravity-augmented COM acceleration'},{'F1':'N','m1':'kg','aC1¹':'m/s²'})],kind='numerical',assumptions=[DOMAIN])
add('capital-lowercase','COM spin moment versus transmitted joint moment',[412,417,419],'The outward pass gives N1=N2=0. Which interpretation is correct?', [('These are zero moments about the point-mass COMs; inward joint moments can still be nonzero','The inward moments include COM-force and downstream-force lever arms.'),('Both actuator torques are zero because n_i and N_i are interchangeable','Capital N_i and lowercase n_i represent different moments.'),('Both link forces F1 and F2 must vanish','The masses may have nonzero translational acceleration and support force.'),('Only gravitational torques remain; all acceleration torques disappear','Offset translational inertia still creates acceleration-dependent torque.')], 'The zero COM tensors remove local rotational inertia moments, while offset forces generate moments about joints.',trap='Case matters: N_i is the COM spin moment, n_i the inward transmitted moment.')
add('angular-link2','Inherited and relative angular motion',[413,414],'For q1dot=3, q2dot=−1 rad/s and q1ddot=−2, q2ddot=5 rad/s², which pair is (omega2,z, alpha2,z)?', [('(2 rad/s,3 rad/s²)','Add inherited and relative quantities separately.'),('(4 rad/s,−7 rad/s²)','This subtracts the second-joint quantities.'),('(−1 rad/s,5 rad/s²)','This retains only relative joint2 motion.'),('(3 rad/s,−2 rad/s²)','This retains only inherited joint1 motion.')], 'Both parallel revolute joints contribute to the second link’s absolute angular motion.',steps=['omega2,z=3+(−1)=2 rad/s.','alpha2,z=−2+5=3 rad/s².','The angular transport cross term is zero because the axes are parallel.'],formulas=[KIN],kind='numerical')
add('elbow-com-coincidence','When the first COM equals the elbow origin',[407,415],'Which assumption specifically permits a2²=R21 aC1¹ in the worked outward pass?', [('The first COM lies at link1’s distal endpoint, exactly at the elbow origin','The same physical point then has the same acceleration before basis conversion.'),('Any point mass anywhere on link1 has the elbow’s acceleration','A different location generally has different tangential and centripetal terms.'),('The links have equal lengths','Length equality is neither stated nor required.'),('The second joint rate is zero','The elbow origin’s location is independent of rotation about that same origin.')], 'Point-mass idealization alone is insufficient. The specified distal location makes the first COM coincide with the next frame origin.',trap='“Point mass” and “point mass at the elbow” are not interchangeable assumptions.')
add('angle-sum','Gravity projection and angle-sum shorthand',[415],'In the final expression for a2², what does g s12 represent?', [('g sin(theta1+theta2)','s12 abbreviates the sine of the combined link orientation.'),('g sin(theta1) sin(theta2)','This is a product, not the angle-sum identity.'),('g sin(theta1−theta2)','The forward frame orientations add in this convention.'),('g[sin(theta1)+sin(theta2)]','The sine of a sum is not generally a sum of sines.')], 'The expanded gravity terms are g cos(theta2) sin(theta1)+g sin(theta2) cos(theta1), equal to g sin(theta1+theta2).',steps=['Collect the two gravity terms in a2,x.','Apply sin(A+B)=sin A cos B+cos A sin B.','Obtain g sin(theta1+theta2).'],formulas=[ACC2],kind='derivation')
add('elbow-acceleration','Frame2 origin acceleration',[415],'Let l1=1 m, theta1=0°, theta2=90°, q1dot=2 rad/s, q1ddot=3 rad/s² and g=10 m/s². What is a2²?', [('(13,4,0) m/s²','Rotate aC1¹=(−4,13,0) by−90°.'),('(−4,13,0) m/s²','This is the same physical augmented acceleration still in frame1.'),('(−13,−4,0) m/s²','This applies the reverse frame rotation.'),('(3,4,0) m/s²','This drops the gravity projection.')], 'The elbow acceleration contains first-link tangential/centripetal effects plus gravity, expressed in the second frame.',steps=['aC1¹=(−1×2²,1×3+10,0)=(−4,13,0).','R21 at90° maps (x,y) to(y,−x).','Thus a2²=(13,4,0) m/s².'],formulas=[ACC1,ACC2],kind='numerical',assumptions=[DOMAIN])
add('elbow-acceleration','Frame2 origin acceleration',[415],'Why does the physical acceleration of the frame2 origin not acquire q2dot or q2ddot terms in this model?', [('Joint2 rotates about that origin; its position is set by link1, although its coordinate components depend on theta2','Changing the attached axes does not move their common elbow origin.'),('Joint2 is assumed locked throughout the example','The later equations retain both q2dot and q2ddot.'),('The second mass is assumed zero','m2 is retained in the force and torque equations.'),('The origin acceleration is always zero because it is a joint center','The elbow moves with link1 even though it is the center of joint2.')], 'Position motion of the elbow comes from joint1. Rotation of its coordinate basis is separate from translation of the physical point.',kind='scenario',difficulty='medium',trap='A time derivative of rotating-frame components is not automatically physical acceleration.')
add('second-com-acceleration','Second COM acceleration from the elbow',[416],'For the same vertical-plane model, l1=1 m, l2=0.5 m, theta1=0°, theta2=90°, qdot=(2,−1) rad/s, qddot=(3,1) rad/s² and g=10 m/s², what is aC2²?', [('(12.5,6,0) m/s²','a2²=(13,4,0), and the local offset adds(−0.5,2,0).'),('(13,4,0) m/s²','This is the elbow-origin acceleration, before the COM offset.'),('(11,5.5,0) m/s²','This uses only joint1 rate/acceleration for the second-link offset.'),('(10.5,6,0) m/s²','This replaces (2−1)² by 2²+(−1)², losing the mixed term.')], 'Both the moving elbow and the second link’s absolute angular motion contribute to its distal mass acceleration.',steps=['From the first-link propagation, a2²=(13,4,0) m/s².','Total angular rate=2−1=1 rad/s; total angular acceleration=3+1=4 rad/s².','Offset acceleration=(−0.5×1²,0.5×4,0)=(−0.5,2,0).','Add the vectors to get(12.5,6,0) m/s².'],formulas=[ACC2],kind='numerical',assumptions=[DOMAIN])
add('mixed-rate-term','Squaring the absolute angular rate',[416],'Which term is lost if (q1dot+q2dot)² is incorrectly replaced by q1dot²+q2dot² in aC2,x?', [('−2 l2 q1dot q2dot','It is the omitted cross term with the centripetal minus sign.'),('+2 l2 q1dot q2dot','The x centripetal term carries a minus sign.'),('−l2 q2dot²','The proposed replacement still retains this square.'),('−l2 q1dot²','The proposed replacement still retains this square.')], 'The second link rotates at the sum of the two joint rates; squaring that sum produces the mixed velocity contribution.',steps=['Expand (q1dot+q2dot)²=q1dot²+2 q1dot q2dot+q2dot².','Multiply by the existing −l2 factor.','The omitted contribution is −2 l2 q1dot q2dot.'],formulas=[ACC2],kind='derivation')
add('zero-spin-nonzero-translation','Zero link2 spin does not mean zero COM acceleration',[413,415,416],'Let g=0, l1=1 m, theta2=90°, qdot=(2,−2) rad/s and qddot=(0,0). Which statement is correct at that instant?', [('omega2=0 but aC2²=(0,4,0) m/s² because the elbow accelerates','The second-link offset has zero local angular contribution, but its moving origin does not.'),('omega2=0 and aC2²=0 because the second link has no absolute spin','Zero spin does not remove the origin’s translation.'),('omega2,z=−2 rad/s and aC2² has a −4 l2 x2 term','This uses only the second relative rate, not the absolute sum.'),('omega2,z=4 rad/s and aC2² has a −16 l2 x2 term','This takes absolute values rather than signed joint rates.')], 'Equal and opposite joint rates can cancel the second link’s absolute rotation while leaving translational motion inherited from the elbow.',steps=['omega2,z=2−2=0 and alpha2,z=0.','The frame2 origin acceleration is(−l1 cos90×4,l1 sin90×4,0)=(0,4,0).','Both local COM-offset terms vanish, so aC2²=a2².'],formulas=[KIN,ACC2],kind='derivation',difficulty='hard',assumptions=[DOMAIN],trap='Zero angular velocity is not zero rigid-body motion.')
add('second-force','Second-link force and COM spin moment',[417],'If m2=2 kg and the gravity-augmented aC2²=(12.5,6,0) m/s², which pair is (F2,N2) for the point-mass model?', [('((25,12,0) N,(0,0,0) N·m)','Force is m2 aC2; COM spin inertia is zero.'),('((12.5,6,0) N,(0,0,0) N·m)','This omits the mass multiplier.'),('((0,0,0) N,(0,0,0) N·m)','Zero COM inertia does not imply zero force.'),('((25,12,0) N,(0,0,12) N·m)','A nonzero joint-offset moment is not the COM spin moment N2.')], 'Newton’s force equation retains the finite point mass, while Euler’s local spin moment is zero at that point.',steps=['F2=m2 aC2=2(12.5,6,0)=(25,12,0) N.','I_C2=0 under the point-mass assumption.','Therefore N2=I_C2 alpha2+omega2×(I_C2 omega2)=0.'],formulas=[form('F2=m2 aC2²; N2=I_C2 alpha2+omega2×(I_C2 omega2)',{'F2':'second mass force in frame2','m2':'second point mass','aC2²':'augmented COM acceleration in frame2','N2':'moment about second COM in frame2','I_C2':'COM inertia tensor','alpha2':'angular acceleration','omega2':'angular velocity'},{'F2':'N','m2':'kg','aC2²':'m/s²','N2':'N·m','I_C2':'kg·m²','alpha2':'rad/s²','omega2':'rad/s'},['I_C2=0 for the point mass.'])],kind='numerical')
RECUR=form('f_i=R_i,i+1 f_(i+1)+F_i; n_i=N_i+R_i,i+1 n_(i+1)+rCi×F_i+p_i,i+1×(R_i,i+1 f_(i+1)); tau_i=n_i·z_i',{'f_i,f_(i+1)':'transmitted forces expressed in their own link frames','F_i':'own mass force in frame i','n_i,n_(i+1)':'transmitted moments about respective frame origins','N_i':'own COM spin moment in frame i','R_i,i+1':'rotation from downstream frame to frame i','rCi':'origin i to COM i, in frame i','p_i,i+1':'origin i to next origin, in frame i','tau_i':'revolute actuator torque','z_i':'positive unit joint axis in frame i'},{'f_i,f_(i+1),F_i':'N','n_i,n_(i+1),N_i,tau_i':'N·m','rCi,p_i,i+1':'m','R_i,i+1,z_i':'dimensionless'},[DOMAIN])
MASS=form('tau=M(q) qddot+h(q,qdot)+G(q); M11=(m1+m2)l1²+m2 l2²+2m2 l1 l2 cos(theta2); M12=M21=m2 l2²+m2 l1 l2 cos(theta2); M22=m2 l2²',{'tau':'2-vector of required joint torques','qddot':'2-vector of joint accelerations','M11,M12,M21,M22':'entries of joint-space inertia matrix M','h':'velocity-product torque vector','G':'gravity-compensation torque vector','m1,m2':'endpoint masses','l1,l2':'link lengths','theta2':'relative elbow angle'},{'tau,h,G':'N·m','qddot':'rad/s²','M11,M12,M21,M22':'kg·m²','m1,m2':'kg','l1,l2':'m','theta2':'rad'},['Derived by collecting acceleration coefficients from the displayed source torques.',DOMAIN])
note(418,'Printed15 inward link2 force f2=R23 f3+F2 simplifies to f2=F2 because terminal f3=0. Expanded expression repeats F2 but establishes its role as transmitted force.')
note(419,'Printed16 inward moment has N2, rotated n3 and terminal-force offset terms struck through in blue; only rC2 cross F2 survives. n2 lies along z and equals m2 l1 l2 c2 q1ddot+m2 l1 l2 s2 q1dot²+m2 l2 g c12+m2 l2²(q1ddot+q2ddot).')
note(420,'Printed17 f1=R12 f2+F1. Rotation is +theta2, opposite outward component conversion; force contributions cannot be added in their original different bases.')
note(421,'Printed18 n1=N1+R12 n2+rC1 cross F1+p12 cross R12 f2. N1 absent after zero-inertia assumption. A stray superscript T is visibly printed after an already-column n2 vector in the first expanded term; literal matrix multiplication with that transpose would be invalid. General equation and following page use a column.')
note(422,'Printed19 expands [p12]cross R12 to rows[0,0,0],[0,0,−l1],[l1 s2,l1 c2,0]. Bottom row expands downstream moment. Gravity combination m2 l1 g(s2 s12+c2 c12) simplifies to m2 l1 g c1 on next page.')
note(423,'Printed20 colors group inertia, velocity-product and gravity terms. Extracts z components for tau1,tau2. tau1 has −m2 l1 l2 s2 q2dot²−2m2 l1 l2 s2 q1dot q2dot; pure q1dot² terms cancel there but +m2 l1 l2 s2 q1dot² remains in tau2. Both gravity cosines and both acceleration couplings are explicit.')
note(424,'Printed21 torques depend on joint positions, velocities and accelerations; even simple2DOF closed forms are lengthy and six-DOF expressions more involved. This is a qualitative complexity observation, not an exponential runtime claim.')
note(425,'Printed22 two-pass summary: outward link1 to n computes velocities/accelerations and applies Newton–Euler per link; inward n to1 starts with given end-effector interaction wrench and computes actuator torques.')
note(426,'Printed23 bibliography: Craig2005 robotics mechanics/control and Merzouki et al2013 intelligent mechatronic systems.','References only; no additional examinable technical proposition.')
note(427,'Printed24 centered Thank You with course footer logos.','Closing page only; no technical content.')
issue(421,'A transpose superscript is printed after a vertically arranged 3x1 n2 vector in an expanded R12 n2 product. Applying it literally makes a3x3 times1x3 product invalid. Use the dimensionally consistent general recursion and the next page’s column-vector expansion, and disclose the printing inconsistency.')
add('inward-force','Why terminal link force equals its mass force',[418],'Why does f2=F2 hold in this example, rather than as a universal identity?', [('The downstream terminal force f3 is zero','The general recursion is f2=R23 f3+F2.'),('The zero COM inertia tensor makes every downstream force vanish','COM inertia does not determine the boundary contact force.'),('Force rotation is unnecessary in every planar manipulator','Nonzero downstream forces still need consistent coordinates.'),('Internal and external forces are always represented by the same symbol','The two quantities have different definitions; equality here follows from the boundary condition.')], 'The terminal boundary removes the rotated downstream-force term only for this particular example.',formulas=[RECUR])
add('last-joint-moment','Distal joint moment from the mass force',[419],'With rC2=(0.5,0,0) m and F2=(25,12,0) N, both expressed in frame2, what is tau2 when N2=f3=n3=0?', [('6 N·m','The z moment is0.5×12.'),('12.5 N·m','The x force is parallel to the offset and does not generate the z moment.'),('−6 N·m','This reverses r×F to F×r.'),('18.5 N·m','This adds radial and tangential force components before multiplying by the length.')], 'Only the transverse force component contributes about the elbow z axis.',steps=['n2=rC2×F2=(0,0,0.5×12).','Thus n2=(0,0,6) N·m.','Project onto +z2 to obtain tau2=6 N·m.'],formulas=[RECUR],kind='numerical',assumptions=['The stated vectors are in the same frame2 basis; all omitted downstream and COM-spin moments are zero.'])
add('last-joint-moment','Distal joint moment from the mass force',[419],'Which terms are removed by the shown assumptions from n2=N2+R23 n3+rC2×F2+p23×(R23 f3)? Select all that apply.', [('N2, because the point-mass COM inertia is zero','This removes the local spin moment, not rC2×F2.'),('R23 n3 and p23×(R23 f3), because the terminal wrench is zero','Both boundary moment and boundary-force offset vanish.'),('rC2×F2, because the COM inertia tensor is zero','The offset force moment generally survives.'),('Every term containing l2, because the mass has zero physical size','l2 is the joint-to-mass offset, not the size of the ideal mass.')], 'The blue strikes remove the COM spin and boundary-load terms. The surviving offset mass force produces the elbow torque.',correct=(0,1),kind='multiple_select',formulas=[RECUR])
add('inward-rotation','Rotate the downstream force before adding',[420],'Suppose theta2=90°, f2²=(25,12,0) N and F1¹=(−4,23,0) N. What is f1¹?', [('(−16,48,0) N','R12 f2=(−12,25,0), then add F1.'),('(21,35,0) N','This adds components from different frames without rotation.'),('(8,−2,0) N','This uses R21 instead of R12.'),('(−12,25,0) N','This rotates correctly but omits the first mass force.')], 'The inward pass rotates from frame2 back into frame1 before adding the own-link force.',steps=['R12=Rz(+90°), so R12 f2²=(−12,25,0) N.','Add F1¹=(−4,23,0) N.','Obtain f1¹=(−16,48,0) N.'],formulas=[RECUR],kind='numerical')
add('inward-moment-terms','Separate own and downstream moment arms',[421],'For the point-mass model with no terminal wrench, which expression retains every surviving contribution to n1?', [('R12 n2+rC1×F1+p12×(R12 f2)','It includes transmitted couple, own mass-force moment and downstream force moment.'),('R12 n2+rC1×F1','This drops the downstream force moment about origin1.'),('rC1×F1+p12×(R12 f2)','This drops the transmitted elbow couple.'),('R12 n2+rC1×(F1+f2)','This adds force components from different frames and uses no explicit downstream conversion.')], 'The elbow transmits both a force and a moment. The first mass adds its own force moment about the base joint.',formulas=[RECUR],trap='Transmitting a couple and translating a force are distinct operations.')
add('source-transpose','Checking the printed vector transpose',[421,422],'An expanded term on printed slide18 places a transpose mark after a displayed3×1 n2 column. Which reading is consistent with R12 being3×3 and with the next slide?', [('Use R12 n2 with n2 as a3×1 column; treat the extra transpose mark as inconsistent typography','Then the product is3×1 and can be added to the other moment vectors.'),('Use R12 n2ᵀ literally, producing a3×1 result','A3×3 matrix cannot multiply a1×3 row on the right.'),('Transpose the whole product to obtain a scalar joint torque immediately','A transpose alone does not project a vector onto the joint axis.'),('Replace the product by the elementwise product of R12 and n2','The recursion requires coordinate rotation, not elementwise multiplication.')], 'The dimensionally consistent general recursion and the following expansion both use a column moment vector. The visible extra transpose is preserved as a source caveat, not silently adopted.',kind='derivation',steps=['R12 has shape3×3.','A moment vector n2 has shape3×1.','R12 n2 has shape3×1; R12 n2ᵀ is not a conformable matrix product.'])
add('skew-rotation-product','Expanding the moment-arm rotation product',[422],'Let p12=(l1,0,0) in frame1. What is the third row of [p12]× Rz(theta2)?', [('(l1 sin(theta2),l1 cos(theta2),0)','Multiply the row(0,l1,0) by Rz(theta2).'),('(−l1 sin(theta2),l1 cos(theta2),0)','This uses the reverse rotation angle.'),('(l1 cos(theta2),l1 sin(theta2),0)','This swaps the sine and cosine positions.'),('(0,l1,0)','This omits the rotation after the cross-product operator.')], 'The row extracts the correct frame1 y component of the rotated downstream force and multiplies by l1.',steps=['The third row of [p12]× is(0,l1,0).','The second row of Rz(theta2) is(sin(theta2),cos(theta2),0).','Their product is l1 times that second rotation row.'],formulas=[form('[p12]× R12 row3=[l1 sin(theta2),l1 cos(theta2),0]',{'p12':'origin1-to-origin2 offset in frame1','R12':'rotation from frame2 into frame1','l1':'first-link length','theta2':'relative elbow angle'},{'p12,l1':'m','R12':'dimensionless','theta2':'rad'})],kind='derivation')
add('gravity-simplification','Gravity combination in the first-joint moment',[422,423],'Which identity reduces sin(theta2)sin(theta1+theta2)+cos(theta2)cos(theta1+theta2)?', [('cos(theta1)','It is cos[(theta1+theta2)−theta2].'),('cos(theta1+2theta2)','This incorrectly uses a plus in the cosine-difference identity.'),('sin(theta1)','The sum is a cosine difference, not a sine difference.'),('cos(theta2)','Both terms still depend on the orientation theta1.')], 'The downstream gravity force’s first-link lever arm depends on theta1 after both coordinate projections are combined.',steps=['Use cos(A−B)=cos A cos B+sin A sin B.','Set A=theta1+theta2 and B=theta2.','A−B=theta1.'],kind='derivation')
add('velocity-cancellation','Cancellation of the first squared-rate torque term',[423],'In tau1, why do the intermediate +k q1dot² and −k(q1dot+q2dot)² terms leave no isolated q1dot² term, where k=m2 l1 l2 sin(theta2)?', [('Their difference is −k(q2dot²+2 q1dot q2dot)','The q1dot² coefficients cancel algebraically.'),('All velocity terms cancel because the COM inertia is zero','The mixed and q2dot² terms remain.'),('The difference is −k q2dot² only','This drops the mixed product2 q1dot q2dot.'),('The difference is +k(q2dot²+2 q1dot q2dot)','This reverses the subtraction sign.')], 'The absence of a pure q1dot² term in tau1 is a cancellation between transmitted and offset-force moments, not a gravity or zero-inertia simplification.',steps=['Expand −k(q1dot+q2dot)².','Combine its −k q1dot² with the separate +k q1dot².','The remaining terms are −k q2dot²−2k q1dot q2dot.'],formulas=[DYN],kind='derivation',trap='Do not delete the corresponding +k q1dot² term in tau2.')
add('torque-projection','Extracting the signed actuator torque',[423],'Why are the z components of n1 and n2 selected as actuator torques here?', [('Each revolute joint’s allowed rotation is about its positive z axis','The scalar effort is n_i dot z_i.'),('The norm of n_i is always the signed actuator torque','Norm discards sign and is not generally the joint-axis projection.'),('The x axes follow the links, so the x moment components should be selected','The revolute axes are z, not the link directions.'),('Every component of a moment vector can independently be commanded by one revolute joint','A one-DOF revolute actuator supplies one scalar generalized effort.')], 'Joint torque is the signed moment component along the permitted rotation axis, not a generic moment magnitude.',kind='conceptual',formulas=[RECUR])
add('torque-numerical','Computing both actuator torques',[423],'Use l1=l2=1 m, m1=m2=1 kg, theta1=0°, theta2=90°, qdot=(1,2) rad/s, qddot=(3,4) rad/s² and g=10 m/s². What are(tau1,tau2)?', [('(25,8) N·m','Inertia(13,7)+velocity(−8,1)+gravity(20,0).'),('(33,7) N·m','This omits all velocity-product terms.'),('(5,8) N·m','This omits the first-joint gravity contribution.'),('(41,6) N·m','This reverses both velocity-product signs.')], 'Compute inertia, velocity-product and gravity contributions separately before adding them; this avoids losing the asymmetric velocity terms.',steps=['At theta2=90°, M=[[3,1],[1,1]], so M qddot=(13,7) N·m.','h=(−(2²+2×1×2),1²)=(−8,1) N·m.','G=(20,0) N·m because cos0=1 and cos90=0.','Add the three vectors to obtain(25,8) N·m.'],formulas=[DYN,MASS],kind='numerical',difficulty='hard',assumptions=[DOMAIN])
add('mass-matrix','Collecting the joint-space inertia matrix',[423],'Define M by tau=M qddot+h+G. Which pair gives the off-diagonal entries M12 and M21?', [('Both equal m2 l2²+m2 l1 l2 cos(theta2)','Collect the q2ddot coefficient in tau1 and q1ddot coefficient in tau2.'),('M12=m2 l2² and M21=m2 l1 l2 cos(theta2)','Each expression drops a term from the same coefficient.'),('Both equal2m2 l1 l2 cos(theta2)','The doubled coupling belongs to part of M11, not these entries.'),('M12=−M21=m2 l2²+m2 l1 l2 cos(theta2)','The inertia matrix is symmetric here, not skew-symmetric.')], 'Both acceleration cross-couplings come from the second mass and have identical coefficients.',steps=['Read every q2ddot term in tau1: m2 l2²+m2 l1 l2 cos(theta2).','Read every q1ddot term in tau2: the same sum.','Thus M12=M21.'],formulas=[DYN,MASS],kind='derivation')
add('mass-matrix','Collecting the joint-space inertia matrix',[423],'With l1=l2=1 m, m1=m2=1 kg and theta2=0, what is M?', [('[[5,2],[2,1]] kg·m²','M11=2+1+2=5, M12=M21=1+1=2, M22=1.'),('[[3,1],[1,1]] kg·m²','This is the right-angle theta2=90° matrix.'),('[[4,2],[2,1]] kg·m²','This omits the first endpoint mass contribution to M11.'),('[[5,1],[2,1]] kg·m²','This loses one term from M12 and destroys the correct symmetry.')], 'The straight configuration increases the coupling terms but does not make this positive-mass inertia matrix singular.',steps=['cos theta2=1.','M11=(1+1)1²+1×1²+2×1×1×1=5.','M12=M21=1+1=2 and M22=1.'],formulas=[MASS],kind='numerical',assumptions=[DOMAIN])
add('inertia-versus-kinematic-singularity','Kinematic singularity versus inertia singularity',[407,423],'For m1,m2,l1,l2>0, det M=m2 l1² l2²[m1+m2 sin²(theta2)]. What follows at the straight configuration theta2=0?', [('M remains invertible although the planar position Jacobian is singular','det M=m1 m2 l1² l2²>0; the two matrices represent different maps.'),('M must be singular whenever the position Jacobian is singular','The determinant given in the stem contradicts this conflation.'),('M is invertible only if l1=l2','Positive unequal lengths also give a positive determinant.'),('M has a negative determinant because sin(theta2)=0','The remaining product is strictly positive under the stated assumptions.')], 'Loss of an instantaneous Cartesian direction does not erase the independent kinetic energy of two positive endpoint masses.',steps=['Set sin²0=0 in the stated determinant.','The remaining product m1 m2 l1² l2² is positive.','Therefore M is invertible; this does not alter the separate straight-arm position singularity.'],formulas=[MASS],kind='derivation',difficulty='medium',assumptions=['The determinant is a derived consequence of the source torque coefficients. The planar straight-arm kinematic singularity is explicitly supplied here for comparison.'])
add('gravity-torques','Static gravity compensation',[423],'At rest with l1=l2=1 m, m1=m2=1 kg, theta1=theta2=0 and g=10 m/s², what torques hold the horizontal arm?', [('(30,10) N·m','Joint1 supports both masses through l1 plus the distal mass through l2; joint2 supports the distal mass through l2.'),('(20,10) N·m','This omits the distal mass’s extra l2 lever arm about joint1.'),('(10,10) N·m','This omits the first-link lever arms of both masses at joint1.'),('(−30,−10) N·m','These signs correspond to gravity’s downward moment, not the positive actuator compensation.')], 'The required actuator torques oppose physical gravity and are positive under the chosen counterclockwise angle convention.',steps=['Set all rates and accelerations to zero.','tau1=m2 l2 g+(m1+m2)l1 g=10+20=30 N·m.','tau2=m2 l2 g=10 N·m.'],formulas=[DYN],kind='numerical',assumptions=[DOMAIN])
add('gravity-torques','Static gravity compensation',[423],'With both links aligned vertically upward(theta1=90°, theta2=0) and all rates and accelerations zero, what does the model predict?', [('Both holding torques are zero, but internal support forces need not be zero','Gravity acts along the aligned links, giving no joint-axis moment.'),('Both torques equal their horizontal-arm values','The gravity lever arms depend on the cosines of orientation.'),('Both masses experience zero gravity force','Zero moment is not zero force.'),('Joint2 torque is zero but joint1 must equal(m1+m2)l1 g','cos theta1 is zero, so that joint1 term also vanishes.')], 'The vertical orientation removes gravitational moment arms. It does not remove weight or axial structural loading.',formulas=[DYN],assumptions=[DOMAIN])
add('rate-reversal','Simultaneous reversal of joint rates',[423],'At the same joint positions and accelerations, both joint rates are reversed simultaneously. With this frictionless model, how do the required torques change?', [('They stay unchanged because every velocity-dependent term is quadratic in the joint rates','Squares and the product q1dot q2dot remain unchanged.'),('Every torque reverses sign','Acceleration and gravity terms remain, and the quadratic rate terms are even.'),('Only the mixed q1dot q2dot term reverses sign','Changing both factors leaves their product unchanged.'),('Only the pure squared-rate terms reverse sign','Squaring removes the sign of each rate.')], 'The model has velocity-product inertial terms but no friction term odd in velocity. Simultaneous rate reversal leaves all displayed torque terms unchanged.',steps=['q1dot² and q2dot² are invariant under sign reversal.','(−q1dot)(−q2dot)=q1dot q2dot.','q, qddot and g are unchanged, so every contribution is unchanged.'],formulas=[DYN],kind='derivation',difficulty='medium',assumptions=[DOMAIN])
add('velocity-coupling','Nonzero coupling torque at a joint with zero acceleration',[423],'Set g=0, l1=l2=1 m, m1=m2=1 kg, theta2=90°, qdot=(2,0) rad/s and qddot=(0,0). What are(tau1,tau2)?', [('(0,4) N·m','tau1 rate terms require q2dot; tau2 retains q1dot².'),('(0,0) N·m','Zero angular acceleration does not remove all velocity-product torques.'),('(−4,0) N·m','This places the surviving squared-rate term at the wrong joint and sign.'),('(4,4) N·m','The isolated q1dot² contribution cancels in tau1, not tau2.')], 'Maintaining the second relative angle during first-joint rotation can require a second actuator torque even when both angular accelerations are zero.',steps=['All inertia-acceleration and gravity terms vanish.','tau1=−sin90(0²+2×2×0)=0.','tau2=sin90×2²=4 N·m.'],formulas=[DYN],kind='numerical',assumptions=[DOMAIN])
add('dynamics-inputs','Inputs to inverse dynamics',[424,425],'Which input/output description matches the computation in this lecture?', [('Given joint positions, rates, accelerations and terminal interaction wrench, compute required actuator torques','That is the two-pass inverse-dynamics task.'),('Given joint torques alone, compute joint positions without initial conditions','Forward time evolution also needs state and integration information.'),('Given only joint positions, compute every torque for every possible motion','Velocity and acceleration contributions depend on the prescribed motion.'),('Given only the endpoint position, uniquely recover all dynamic parameters','The example assumes link masses/lengths and motion information.')], 'The calculation evaluates actuator requirements for a prescribed motion and boundary load. It does not integrate an unknown future trajectory.',kind='definition',difficulty='easy')
add('two-pass-order','Outward then inward Newton–Euler passes',[425],'Which sequence respects the dependencies of the recursive inverse-dynamics algorithm?', [('Outward kinematics and link inertia forces/moments, then inward transmitted loads and actuator efforts','The inward pass uses quantities computed in the outward pass.'),('Inward actuator torques first, then compute the COM accelerations needed to obtain those torques','This reverses the dependency.'),('Outward force recursion from the base load, then inward joint velocities from the terminal load','This swaps the data and propagation directions.'),('Perform only the outward pass because the local COM moment already equals joint torque','The inward lever-arm and downstream-load accumulation is still required.')], 'Motion propagates outward from the base; required loads propagate inward from the prescribed terminal boundary.',kind='sequence',difficulty='medium',steps=['Initialize the fixed-base/gravity data and prescribed joint motion.','Compute link velocities, accelerations, F_i and N_i outward.','Initialize the terminal wrench and propagate f_i,n_i inward.','Project each joint moment onto its positive joint axis.'])
add('model-scope','Changing the mass distribution changes the model',[407,408,424],'A designer replaces the endpoint point masses with uniform massive rods. Can the displayed torque formulas be used unchanged merely by calling m1,m2 the rod masses?', [('No; COM offsets and nonzero COM inertia tensors must be changed before recomputing dynamics','The original rCi=li xi and I_Ci=0 no longer describe uniform rods.'),('Yes; only total mass matters in rigid-link inverse dynamics','Mass location and inertia distribution also matter.'),('Yes; the zero terminal wrench removes any influence of mass distribution','A boundary condition does not remove link inertia.'),('No; the Newton–Euler method itself becomes inapplicable','The method still applies after supplying the correct mass properties.')], 'The equations are specific to a chosen mass model, while the recursive method can handle other mass distributions.',kind='scenario',assumptions=['This is a model-scope comparison, not a claim that the supplied slides derive uniform-rod formulas.'])
add('first-mass-second-torque','Why the first mass is absent from tau2',[407,423],'Why does m1 not appear in the displayed tau2 expression?', [('The first point mass is at the elbow axis, so changing joint2 alone does not move it','Its generalized inertial/gravity contribution to joint2 is zero in this model.'),('All masses upstream of a joint are omitted from every joint torque','The first mass still contributes to tau1; the reason depends on geometry.'),('m1 is assumed equal to zero','The source retains finite m1 contributions in tau1.'),('The second joint is assumed unactuated','The calculation explicitly obtains a nonzero required tau2.')], 'Joint2 rotation moves the second mass relative to the elbow but does not move the first mass sitting on that axis.',kind='diagram',assumptions=[DOMAIN])
add('collinear-velocity-terms','Collinearity removes velocity terms, not inertia coupling',[423],'At theta2=0, which statements follow for arbitrary instantaneous joint rates? Select all that apply.', [('All displayed velocity-product torque terms vanish because they contain sin(theta2)','Both h1 and h2 have the common sine factor.'),('Acceleration coupling generally remains because it contains cos(theta2)=1','The off-diagonal inertia coefficients need not vanish.'),('Every required actuator torque is zero','Acceleration and gravity terms can remain.'),('The links have no centripetal COM acceleration','Local squared-rate accelerations can be nonzero even when their generalized velocity torques cancel.')], 'Torque-term cancellation is not absence of all physical acceleration. The final generalized equations separate these effects.',correct=(0,1),kind='multiple_select',formulas=[DYN,MASS],assumptions=[DOMAIN],trap='A zero generalized velocity term does not mean every local acceleration term is zero.')
add('terminal-couple-extension','Adding a nonzero terminal boundary moment',[419,421,425],'As an explicit extension, keep terminal force f3=0 but set the inward-recursion boundary moment n3=(0,0,M) in the aligned tip frame. What extra actuator effort is required?', [('Add M to both tau1 and tau2','A z couple is unchanged by planar z rotations and is transmitted through both joints.'),('Add M only to tau2','The upstream recursion also includes the transmitted moment.'),('Add M to tau1 and subtract M from tau2','No action/reaction sign has been changed in the specified recursion convention.'),('Add M cos(theta2) to tau1 and M to tau2','A z-directed moment is invariant under a z rotation; the cosine projection is inappropriate.')], 'The original example has n3=0. With the specified nonzero boundary couple, each inward moment acquires the same z component.',steps=['At joint2, R23 n3 adds(0,0,M).','At joint1, R12 rotates that z couple without changing it.','Projecting onto each +z axis adds M to each actuator torque.'],formulas=[RECUR,form('delta tau=[M,M]',{'delta tau':'additional two-joint actuator torque vector','M':'specified terminal transmitted +z couple'},{'delta tau,M':'N·m'},['Use the specified inward-recursion boundary sign, not an oppositely defined environment-on-robot wrench.'])],kind='derivation',assumptions=['Only the terminal moment boundary condition is changed; M is defined by the source recursion sign. The original no-terminal-wrench formula is otherwise retained.'])
